CREATE TABLE public.audit_mp_movements_tmp (audit_key text PRIMARY KEY, account text NOT NULL, date timestamptz, source_id text, record_type text, description text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, external_reference text, payment_method text, gross_amount numeric, fee_amount numeric, net_credit numeric, net_debit numeric, balance numeric, raw jsonb NOT NULL DEFAULT '{}'::jsonb, audited_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.audit_mp_movements_tmp TO service_role; REVOKE ALL ON public.audit_mp_movements_tmp FROM PUBLIC, anon, authenticated; ALTER TABLE public.audit_mp_movements_tmp ENABLE ROW LEVEL SECURITY; COMMENT ON TABLE public.audit_mp_movements_tmp IS 'Read-only Mercado Pago report snapshots; service-only; no cash flow or bank transaction writes.';